\title{A Degree--Parity Obstruction to Rational Solutions of the Airy Riccati Equation}
\author{Aristotle}
\date{June 26, 2026}

\begin{document}

\begin{abstract}
We study the Riccati equation $v' + v^2 = f$ associated, via the logarithmic
derivative substitution $v = y'/y$, with the second-order linear differential
equation $y'' = f\,y$ over the polynomial ring $\RX$. Clearing denominators in a
candidate rational solution $v = p/q$ reduces the existence of a rational solution
to the solvability of the polynomial identity $p'q - p q' + p^2 = f q^2$ with
$q \neq 0$. Our main theorem is a sharp degree--parity obstruction: if $\deg f$
is odd, this identity has no solution with $q \neq 0$, hence $v' + v^2 = f$ has no
rational solution. The proof requires neither coprimality of $p$ and $q$ nor any
pole analysis; it is a pure degree count built on a Wronskian-like degree-drop
lemma $\deg(p'q - p q') \le \deg p + \deg q - 1$. Specializing to $f = X$ yields
the non-existence of a rational solution to the Airy Riccati equation
$v' + v^2 = x$, the genuinely Galois-theoretic reducible-case obstruction for
Airy's equation $y'' = x y$. All results have been formally verified.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Airy's equation and the closed-form question}
Airy's equation
\begin{equation}\label{eq:airy}
  y'' = x\,y
\end{equation}
is among the most ubiquitous second-order linear ODEs in mathematical physics,
governing solutions near a simple turning point: the intensity of light at an
optical caustic, the WKB wavefunction of a quantum particle at a classical
turning point, telescope-aperture diffraction, and (through the Tracy--Widom law)
the edge statistics of large random matrices. Its solutions, the Airy functions
$\mathrm{Ai}(x)$ and $\mathrm{Bi}(x)$, are entire but \emph{non-elementary}.

The modern framework for such statements is differential Galois theory
(Picard--Vessiot theory). For a second-order equation $y'' = f y$ with no
first-order term (so the differential Galois group $G \le \SL_2$), Kovacic's
algorithm is an effective decision procedure whose first branch, the
\emph{reducible case}, tests whether $G$ has a common eigenvector --- equivalently
whether the associated Riccati equation admits a \emph{rational} solution.

\subsection{The Riccati reduction}
The substitution $v = y'/y$ transforms $y'' = f y$ into the first-order quadratic
Riccati equation
\begin{equation}\label{eq:riccati}
  v' + v^2 = f,
\end{equation}
since $v' = y''/y - (y'/y)^2 = f - v^2$. A Liouvillian solution of the linear
equation forces, in the reducible case, an algebraic --- in the simplest instance
rational --- solution of \eqref{eq:riccati}. Closing the door on rational
solutions of \eqref{eq:riccati} therefore closes the most important door to
elementary solutions of \eqref{eq:airy}.

\subsection{Contribution}
We isolate and prove, with a minimal and robust argument, the rational-function
obstruction for the entire odd-degree family: a Wronskian-like degree-drop lemma
(Lemma~\ref{lem:wronsk}), the odd-degree Riccati obstruction
(Theorem~\ref{thm:odd}), the Airy specialization (Theorem~\ref{thm:airy}), and a
combined first-step obstruction (Corollary~\ref{cor:combined}). All statements are
formalized over $\RX$ and machine-checked.

\section{Preliminaries}

We work in $\RX$ with formal derivative $p \mapsto p'$, and use the
natural-number degree $\deg p \in \N$ with $\deg 0 = 0$; leading-behaviour
statements are guarded by nonvanishing hypotheses. We use the standard facts:
\begin{itemize}
  \item[(D1)] For $p, q \neq 0$, $\deg(pq) = \deg p + \deg q$.
  \item[(D2)] For $p \neq 0$, $\deg(p^n) = n \deg p$; in particular
        $\deg(p^2) = 2\deg p$.
  \item[(D3)] $\deg(p') \le \deg p - 1$, with $\deg(p') = 0$ when $\deg p = 0$.
  \item[(D4)] $\deg(a \pm b) \le \max(\deg a, \deg b)$, with equality when the
        degrees differ.
\end{itemize}

\begin{definition}[rational solution]
A \emph{rational solution} of \eqref{eq:riccati} is $v = p/q \in \RrX$ with
$p,q \in \RX$, $q \neq 0$, satisfying $v' + v^2 = f$ in $\RrX$.
\end{definition}

\begin{definition}[polynomial Wronskian]
For $f, g \in \RX$, $W(f,g) := f g' - g f'$.
\end{definition}

\begin{lemma}[clearing denominators]\label{lem:clear}
For $p, q \in \RX$ with $q \neq 0$, the function $v = p/q$ satisfies
$v' + v^2 = f$ in $\RrX$ if and only if
\begin{equation}\label{eq:cleared}
  p'\,q - p\,q' + p^2 = f\,q^2
\end{equation}
holds in $\RX$.
\end{lemma}

\begin{proof}
By the quotient rule $v' = (p'q - p q')/q^2$ and $v^2 = p^2/q^2$, so
$v' + v^2 = (p'q - p q' + p^2)/q^2$. Equating to $f$ and multiplying by
$q^2 \neq 0$ gives \eqref{eq:cleared}; dividing reverses the step.
\end{proof}

\section{The Wronskian-like degree-drop lemma}

\begin{lemma}[\texttt{natDegree\_wronskianLike\_le}]\label{lem:wronsk}
For all $p, q \in \RX$,
\[
  \deg\!\big(p'\,q - p\,q'\big) \le \deg p + \deg q - 1.
\]
\end{lemma}

\begin{proof}
By (D4), $\deg(p'q - p q') \le \max(\deg(p'q), \deg(p q'))$. If $p$ is constant
then $p' = 0$ and $p q'$ has degree $\le \deg q - 1 = \deg p + \deg q - 1$;
symmetrically if $q$ is constant. Otherwise $\deg p, \deg q \ge 1$ and by
(D1),(D3),
\[
  \deg(p'q) \le (\deg p - 1) + \deg q = \deg p + \deg q - 1,\qquad
  \deg(p q') \le \deg p + (\deg q - 1) = \deg p + \deg q - 1,
\]
so the maximum is at most $\deg p + \deg q - 1$.
\end{proof}

This is the polynomial-ring shadow of the classical degeneracy of the Wronskian
of two solutions of a second-order equation.

\section{The odd-degree Riccati obstruction}

\begin{theorem}[\texttt{no\_rational\_solves\_riccati\_odd\_deg}]\label{thm:odd}
Let $f, p, q \in \RX$ with $q \neq 0$ and $\deg f$ odd. Then
\eqref{eq:cleared}, namely $p'q - p q' + p^2 = f q^2$, is impossible.
Consequently $v' + v^2 = f$ has no rational solution.
\end{theorem}

\begin{proof}
Suppose \eqref{eq:cleared} holds; write $d_p = \deg p$, $d_q = \deg q$. Since
$q \neq 0$, by (D1)--(D2),
\begin{equation}\label{eq:rhs}
  \deg(f q^2) = \deg f + 2 d_q,
\end{equation}
which is odd. Set $L := p'q - p q' + p^2$. By Lemma~\ref{lem:wronsk} and (D2),(D4),
\begin{equation}\label{eq:lhs}
  \deg L \le \max\big(d_p + d_q - 1,\ 2 d_p\big).
\end{equation}

\emph{Case 1: $d_p \ge d_q$.} Then $d_p + d_q - 1 \le 2 d_p - 1 < 2 d_p$, so the
$p^2$ term strictly dominates the cross term; its leading term survives (and
$p \neq 0$, since $p = 0$ forces $L = 0 \neq f q^2$), giving $\deg L = 2 d_p$,
even. By \eqref{eq:cleared} this equals $\deg(f q^2)$, odd by \eqref{eq:rhs}: an
even number cannot equal an odd number, a contradiction.

\emph{Case 2: $d_p < d_q$.} Then $2 d_p \le 2 d_q - 2$ and
$d_p + d_q - 1 \le 2 d_q - 2$, so by \eqref{eq:lhs} $\deg L \le 2 d_q - 2$. But by
\eqref{eq:rhs}, $\deg(f q^2) = \deg f + 2 d_q \ge 1 + 2 d_q > 2 d_q - 2$, so the
left side has strictly smaller degree than the right, contradicting
\eqref{eq:cleared}.

Both cases are impossible, so no such $p, q$ exist; by Lemma~\ref{lem:clear},
$v' + v^2 = f$ has no rational solution.
\end{proof}

\begin{remark}
The argument never assumes $\gcd(p,q)=1$: the obstruction is purely metric, hence
stronger than the textbook pole-counting argument. The parity hypothesis is
load-bearing: for even $\deg f$ (e.g.\ $f = X^2$) the clash disappears and
rational Riccati solutions can exist. The proof uses only the parity of $\deg f$,
so it covers the entire odd-degree family uniformly.
\end{remark}

\section{Airy specialization and combined obstruction}

\begin{theorem}[\texttt{no\_rational\_solves\_riccati\_airy}]\label{thm:airy}
There are no $p, q \in \RX$ with $q \neq 0$ satisfying $p'q - p q' + p^2 = X q^2$;
equivalently, $v' + v^2 = x$ has no rational solution.
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:odd} with $f = X$, since $\deg X = 1$ is odd.
\end{proof}

For context we recall the elementary polynomial layer (catalog file
\texttt{EMLDiffObstruction}): $\deg(p'') < \deg(Xp)$ for $p \neq 0$
(\texttt{degree\_second\_deriv\_lt\_degree\_X\_mul}); hence no nonzero polynomial
solves $p'' = Xp$ (\texttt{no\_poly\_solves\_airy}); more generally
$p'' = q p$ is impossible for $\deg q \ge 1$, $p \neq 0$
(\texttt{no\_poly\_solves\_second\_order\_pos\_deg}); $v' + v^2 = X$ has no
polynomial solution (\texttt{no\_poly\_solves\_riccati\_airy}); and if
$f'' = q f$, $g'' = q g$ then $W(f,g)' = 0$
(\texttt{poly\_wronskian\_derivative\_zero}).

\begin{corollary}[\texttt{airy\_no\_poly\_and\_no\_rational\_riccati}]\label{cor:combined}
For Airy's equation $y'' = x y$: (i) no nonzero polynomial is a solution, and
(ii) the associated Riccati equation $v' + v^2 = x$ has no rational solution.
\end{corollary}

\begin{proof}
Part (i) is \texttt{no\_poly\_solves\_airy}; part (ii) is Theorem~\ref{thm:airy}.
\end{proof}

\section{The three-layer obstruction tower}

The results form a strictly increasing tower for $y'' = f y$:
\begin{enumerate}
  \item \textbf{Polynomial layer:} no polynomial solution when $\deg f \ge 1$
        (one-sided degree mismatch: $p''$ too small to equal $f p$).
  \item \textbf{Rational Riccati layer} (this paper): no rational $v = p/q$ when
        $\deg f$ is odd (degree parity); strictly stronger, and the genuine
        reducible-case test of Kovacic's algorithm.
  \item \textbf{Abstract differential-field layer:} over any differential field,
        the Wronskian of two solutions of $y'' = a y$ is constant, pinning the
        solution space at dimension $\le 2$ and $G \le \SL_2$.
\end{enumerate}

\section{Algorithmic reading}

Theorem~\ref{thm:odd} short-circuits the reducible-case search of Kovacic's
algorithm by a single parity test: given $y'' = f y$ with $f \in \RX$, if
$\deg f$ is odd, report ``reducible case fails'' in $O(1)$, without enumerating
candidate numerator/denominator degrees. An exhaustive symbolic search over
bounded-degree $p, q$ corroborates that \eqref{eq:cleared} has no solution for
$f = X, X^3, X^5$ and \emph{does} for representative even-degree $f$, exhibiting
the sharpness of the parity hypothesis.

\section{Applications and significance}

The Airy function is indispensable in optics (caustics, rainbows), quantum
mechanics (turning-point/WKB analysis), diffraction, and random matrix theory
(the Tracy--Widom edge law). Each invokes a function with no elementary closed
form. Theorem~\ref{thm:odd} makes the first and most decisive step of that
impossibility maximally transparent: it depends on a single integer parity and
covers an infinite odd-degree family at once, while offering symbolic-computation
systems an instant negative certificate for the reducible case.

\section{Discussion and future work}

\begin{conjecture}[algebraic obstruction]
For every $f \in \RX$ of odd degree, $v' + v^2 = f$ has no solution algebraic over
$\RrX$. The rational degree/parity dichotomy should be a shadow of a
ramification-parity invariant at infinity: an algebraic $v$ contributes a $v^2$
with even Puiseux valuations, incompatible with the odd pattern forced by
odd-degree $f$.
\end{conjecture}

\begin{conjecture}[Wronskian and dimension]
In any differential field $K$ with constants $C$, the solution set
$\{y : y'' = a y\}$ is a $C$-vector space of dimension $\le 2$, equal to $2$
exactly when a nonzero-Wronskian pair exists; linear dependence is equivalent to
vanishing of the (constant) Wronskian.
\end{conjecture}

\begin{conjecture}[Galois dichotomy]
For $f \in \RX$, the differential Galois group of $y'' = f y$ is reducible only if
$\deg f$ is even; for odd $\deg f$ it is $\SL_2$-large, with Airy ($f = X$) the
minimal instance. Theorem~\ref{thm:odd} is the reducible-case test and shows it
always fails for odd degree.
\end{conjecture}

\section{Conclusion}

A second-order linear ODE as simple as $y'' = x y$ resists every elementary
formula, and the sharpest first reason is the parity of an integer. Clearing
denominators in the associated Riccati equation and counting degrees shows that
for any odd-degree $f$ the equation $v' + v^2 = f$ has no rational solution, with
Airy as the minimal instance. The argument needs no pole analysis and no
coprimality, generalizes across an infinite family, and has been fully
machine-verified.

\end{document}

