function SEARCH_RICCATI(f, max_deg, coeff_set):
  for dq in 0..max_deg:
    for each tuple of dq coefficients from coeff_set as q_tail:
      for q_lead in coeff_set, q_lead != 0:
        q := q_tail ++ [q_lead]          # q has degree dq, q != 0
        for dp in 0..max_deg:
          for each tuple of (dp+1) coefficients from coeff_set as p:
            lhs := p' * q - p * q' + p^2
            rhs := f * q^2
            if lhs - rhs == 0: return (p, q)
  return NONE                            # no rational solution up to the bound

